@extends('layouts.app', ['title' => ($product->exists ? 'Edit' : 'Tambah').' Produk — Lumière Skin'])
@section('content')<a class="link" href="{{ route('admin.products.index') }}">← Kembali</a><h1 class="page-title mt-5">{{ $product->exists ? 'Edit produk' : 'Tambah produk' }}</h1><form method="POST" action="{{ $product->exists ? route('admin.products.update',$product) : route('admin.products.store') }}" class="mt-8 space-y-8">@csrf @if($product->exists)@method('PUT')@endif<div class="rounded-2xl bg-white p-6"><div class="grid gap-5 md:grid-cols-2"><label><span class="label">Nama produk</span><input class="input" name="name" value="{{ old('name',$product->name) }}" required></label><label><span class="label">Deskripsi</span><textarea class="input" name="description" rows="3">{{ old('description',$product->description) }}</textarea></label></div></div><section><div class="flex items-end justify-between"><div><h2 class="font-serif text-3xl text-[#173f35]">Varian</h2><p class="text-sm text-stone-600">Minimal satu varian wajib tersedia.</p></div><button type="button" id="add-variant" class="btn-secondary">Tambah varian</button></div><div id="variants" class="mt-4 space-y-3">@php($variants=old('variants',$product->exists?$product->variants->toArray():[['name'=>'','price'=>'','stock'=>'']]))@foreach($variants as $i=>$variant)<div class="variant grid gap-3 rounded-2xl bg-white p-5 md:grid-cols-[1fr_1fr_1fr_auto]">@if(isset($variant['id']))<input type="hidden" name="variants[{{ $i }}][id]" value="{{ $variant['id'] }}">@endif<label><span class="label">Nama</span><input class="input" name="variants[{{ $i }}][name]" value="{{ $variant['name'] }}" required></label><label><span class="label">Harga</span><input class="input" type="number" min="0" name="variants[{{ $i }}][price]" value="{{ $variant['price'] }}" required></label><label><span class="label">Stok</span><input class="input" type="number" min="0" name="variants[{{ $i }}][stock]" value="{{ $variant['stock'] }}" required></label><button type="button" class="remove self-end px-3 py-2 text-red-700">Hapus</button></div>@endforeach</div></section><div class="flex justify-end"><button class="btn-primary">Simpan produk</button></div></form><template id="variant-template"><div class="variant grid gap-3 rounded-2xl bg-white p-5 md:grid-cols-[1fr_1fr_1fr_auto]"><label><span class="label">Nama</span><input class="input" data-field="name" required></label><label><span class="label">Harga</span><input class="input" type="number" min="0" data-field="price" required></label><label><span class="label">Stok</span><input class="input" type="number" min="0" data-field="stock" required></label><button type="button" class="remove self-end px-3 py-2 text-red-700">Hapus</button></div></template><script>const list=document.querySelector('#variants');document.querySelector('#add-variant').onclick=()=>{const node=document.querySelector('#variant-template').content.cloneNode(true);const i=Date.now();node.querySelectorAll('[data-field]').forEach(el=>el.name=`variants[${i}][${el.dataset.field}]`);list.append(node)};list.addEventListener('click',e=>{if(e.target.classList.contains('remove')&&list.children.length>1)e.target.closest('.variant').remove()});</script>@endsection
